  {"id":"hunter_s_mark","name":{"en":"Hunter's Mark","es":"Marca del cazador"},"level":1,"school":{"en":"Divination","es":"Adivinación"},"castingTime":"Bonus action","range":"90 feet","duration":"Concentration, up to 1 hour","components":"V","classes":["Ranger"],"description_en":"You choose a creature you can see. Until the spell ends, you deal an extra 1d6 damage with weapon attacks against it, and have advantage on Perception/Survival to find it.","description_es":"Eliges a una criatura visible. Hasta el final, le haces +1d6 con armas y tienes ventaja en Supervivencia/Percepción para seguirle."},
  {"id":"identify","name":{"en":"Identify","es":"Identificar"},"level":1,"school":{"en":"Divination (Ritual)","es":"Adivinación (Ritual)"},"castingTime":"1 minute","range":"Touch","duration":"Instantaneous","components":"V, S, M","classes":["Bard","Wizard"],"description_en":"You learn the properties of a magic item (spells affecting it, command word, charges) and learn which spells are affecting a creature.","description_es":"Conoces las propiedades de un objeto mágico (conjuros, palabra de mando, cargas) y qué conjuros afectan a una criatura.","materials":"A pearl worth at least 100 gp"},
  {"id":"inflict_wounds","name":{"en":"Inflict Wounds","es":"Infligir heridas"},"level":1,"school":{"en":"Necromancy","es":"Nigromancia"},"castingTime":"Action","range":"Touch","duration":"Instantaneous","components":"V, S","classes":["Cleric"],"description_en":"Make a melee spell attack against a creature. On a hit, the target takes 3d10 necrotic damage.","description_es":"Haces un ataque cuerpo a cuerpo de conjuro a una criatura. Si impactas, recibe 3d10 necrótico."},
  {"id":"jump","name":{"en":"Jump","es":"Salto"},"level":1,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"Touch","duration":"1 minute","components":"V, S, M","classes":["Druid","Ranger","Sorcerer","Wizard"],"description_en":"You touch a creature. Its jump distance is tripled until the spell ends.","description_es":"Tocas a una criatura. Su distancia de salto se triplica hasta el final.","materials":"A grasshopper's hind leg"},
  {"id":"longstrider","name":{"en":"Longstrider","es":"Paso largo"},"level":1,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"Touch","duration":"1 hour","components":"V, S, M","classes":["Bard","Druid","Ranger","Wizard"],"description_en":"You touch a creature. Its walking speed becomes 10 feet faster until the spell ends.","description_es":"Tocas a una criatura. Su velocidad de caminar aumenta en 3 m hasta el final.","materials":"A pinch of dirt"},
  {"id":"mage_armor","name":{"en":"Mage Armor","es":"Armadura de mago"},"level":1,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"Touch","duration":"8 hours","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"You touch a willing creature that isn't wearing armor, and a protective magical force surrounds it. AC becomes 13 + Dex modifier.","description_es":"Tocas a una criatura voluntaria sin armadura. Una fuerza mágica la protege: CA = 13 + modificador de Destreza.","materials":"A piece of cured leather"},
  {"id":"magic_missile","name":{"en":"Magic Missile","es":"Misil mágico"},"level":1,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"120 feet","duration":"Instantaneous","components":"V, S","classes":["Sorcerer","Wizard"],"description_en":"You create three glowing darts of magical force. Each hits a creature you can see within range (1d4 + 1 force damage each). No attack roll required.","description_es":"Creas tres dardos de fuerza mágica. Cada uno impacta a una criatura visible a 36 m (1d4+1 de fuerza). Sin tirada de ataque."},
  {"id":"protection_from_evil_and_good","name":{"en":"Protection from Evil and Good","es":"Protección contra el bien y el mal"},"level":1,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"Touch","duration":"Concentration, up to 10 minutes","components":"V, S, M","classes":["Cleric","Paladin","Warlock","Wizard"],"description_en":"You protect a willing creature against aberrations, celestials, elementals, fey, fiends, and undead. They can't charm/frighten the target, and the target's saves against their abilities are made with advantage.","description_es":"Proteges a una criatura voluntaria contra aberraciones, celestiales, elementales, feéricos, infernales y no-muertos. No pueden encantarla ni asustarla, y las salvaciones contra sus aptitudes tienen ventaja.","materials":"Holy water or powdered silver"},
  {"id":"purify_food_and_drink","name":{"en":"Purify Food and Drink","es":"Purificar comida y bebida"},"level":1,"school":{"en":"Transmutation (Ritual)","es":"Transmutación (Ritual)"},"castingTime":"Action","range":"10 feet","duration":"Instantaneous","components":"V, S","classes":["Cleric","Druid","Paladin"],"description_en":"You purify up to 10 cubic feet of food or drink, making it free of poison and disease.","description_en":"Purifica hasta 0,3 m³ de comida o bebida, dejándola libre de veneno y enfermedad.","description_es":"Purificas hasta 0,3 m³ de comida o bebida, dejándola libre de veneno y enfermedad.","areaOfEffect":"10 cubic feet"},
  {"id":"sanctuary","name":{"en":"Sanctuary","es":"Santuario"},"level":1,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Bonus action","range":"30 feet","duration":"1 minute","components":"V, S, M","classes":["Cleric"],"description_en":"You ward a creature within range against attack. Until the spell ends, any creature who targets it with an attack or harmful spell must first make a Wisdom save or be forced to choose a new target.","description_es":"Proteges a una criatura contra ataques. Cualquier objetivo que la ataque debe primero superar una salvación de Sabiduría o redirigir la acción.","savingThrow":"Wisdom","materials":"A small silver mirror"},
  {"id":"shield","name":{"en":"Shield","es":"Escudo"},"level":1,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Reaction","range":"Self","duration":"1 round","components":"V, S","classes":["Sorcerer","Wizard"],"description_en":"An invisible barrier of magical force appears and protects you. Until the start of your next turn, you have a +5 bonus to AC and immunity to magic missile.","description_es":"Aparece una barrera invisible de fuerza mágica. Hasta el inicio de tu próximo turno, ganas +5 a CA y eres inmune a Misil Mágico."},
  {"id":"shield_of_faith","name":{"en":"Shield of Faith","es":"Escudo de fe"},"level":1,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Bonus action","range":"60 feet","duration":"Concentration, up to 10 minutes","components":"V, S, M","classes":["Cleric","Paladin"],"description_en":"A shimmering field appears and surrounds a creature of your choice within range, granting it a +2 bonus to AC for the duration.","description_es":"Un campo titilante rodea a una criatura a tu elección a 18 m, dándole +2 a CA.","materials":"A small prayer scroll"},
  {"id":"silent_image","name":{"en":"Silent Image","es":"Imagen silenciosa"},"level":1,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"60 feet","duration":"10 minutes","components":"V, S, M","classes":["Bard","Sorcerer","Wizard"],"description_en":"You create the image of an object, creature, or other visible phenomenon that is no larger than a 15-foot cube. The image is purely visual.","description_es":"Creas la imagen de un objeto, criatura o fenómeno visual que no supere un cubo de 4,5 m. La imagen es solo visual.","areaOfEffect":"15-foot cube","materials":"A bit of fleece"},
  {"id":"sleep","name":{"en":"Sleep","es":"Dormir"},"level":1,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"90 feet","duration":"1 minute","components":"V, S, M","classes":["Bard","Sorcerer","Wizard"],"description_en":"Roll 5d8; creatures in 20-ft radius in ascending order fall unconscious until the total HP is exhausted (no save, ends if damaged).","description_es":"Tira 5d8; las criaturas en un radio de 6 m quedan inconscientes en orden ascendente de pg hasta agotar el total (sin salvación; termina si reciben daño).","areaOfEffect":"20-foot-radius","materials":"A pinch of fine sand, rose petals, or a cricket"},
  {"id":"speak_with_animals","name":{"en":"Speak with Animals","es":"Hablar con animales"},"level":1,"school":{"en":"Divination (Ritual)","es":"Adivinación (Ritual)"},"castingTime":"Action","range":"Self","duration":"10 minutes","components":"V, S","classes":["Bard","Druid","Paladin","Ranger"],"description_en":"You gain the ability to comprehend and verbally communicate with beasts for the duration.","description_es":"Ganas la capacidad de comprender y comunicarte verbalmente con bestias durante la duración."},
  {"id":"thunderwave","name":{"en":"Thunderwave","es":"Ola de trueno"},"level":1,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"Self (15-foot cube)","duration":"Instantaneous","components":"V, S","classes":["Bard","Druid","Sorcerer","Wizard"],"description_en":"Each creature in a 15-foot cube of your choice makes a Constitution save; on fail, 2d8 thunder damage and pushed 10 feet away.","description_es":"Cada criatura en un cubo de 4,5 m hace salvación de Constitución. Falla: 2d8 de trueno y es empujada 3 m.","savingThrow":"Constitution","areaOfEffect":"15-foot cube"},
  {"id":"unseen_servant","name":{"en":"Unseen Servant","es":"Sirviente invisible"},"level":1,"school":{"en":"Conjuration (Ritual)","es":"Conjuración (Ritual)"},"castingTime":"Action","range":"60 feet","duration":"1 hour","components":"V, S, M","classes":["Bard","Warlock","Wizard"],"description_en":"An invisible, mindless, shapeless force performs simple tasks at your command. It can fetch, carry, clean, etc., with 20 ft fly speed and 60 lb strength.","description_es":"Una fuerza invisible, sin mente y sin forma cumple tareas simples. Puede traer, cargar, limpiar, etc., con velocidad 6 m y fuerza 27 kg.","materials":"A bit of string, a bit of wood"},

  # ───────────────────────────── LEVEL 2 ─────────────────────────────────
  {"id":"aid","name":{"en":"Aid","es":"Auxilio"},"level":2,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"30 feet","duration":"8 hours","components":"V, S, M","classes":["Cleric","Paladin"],"description_en":"Your spell bolsters your allies with toughness and resolve. Three willing creatures gain 5 temporary HP and current+max HP increase by that much until the spell ends.","description_es":"Hasta tres criaturas voluntarias ganan 5 pg temporales, y sus pg actuales y máx aumentan igual hasta el final.","materials":"A tiny strip of white cloth"},
  {"id":"alter_self","name":{"en":"Alter Self","es":"Alterar el propio aspecto"},"level":2,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"Self","duration":"Concentration, up to 1 hour","components":"V, S","classes":["Sorcerer","Wizard"],"description_en":"You assume a different form. Choose aquatic adaptation, change appearance, or natural weapons (1d6 unarmed strikes).","description_es":"Asumes otra forma. Elige adaptación acuática (branquias y nadar), cambiar apariencia, o armas naturales (1d6 sin arma)."},
  {"id":"arcane_lock","name":{"en":"Arcane Lock","es":"Cerradura arcana"},"level":2,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"Touch","duration":"Until dispelled","components":"V, S, M","classes":["Wizard"],"description_en":"You touch a closed door, window, gate, chest, or other entryway and it becomes locked. DC 30 pick / Strength checks.","description_es":"Tocas una puerta, ventana, cofre o entrada cerrada y la sellas. Ganzúa DC 30 / pruebas de Fuerza.","materials":"Gold dust worth at least 25 gp"},
  {"id":"augury","name":{"en":"Augury","es":"Augurio"},"level":2,"school":{"en":"Divination (Ritual)","es":"Adivinación (Ritual)"},"castingTime":"1 minute","range":"Self","duration":"Instantaneous","components":"V, S, M","classes":["Cleric"],"description_en":"By casting gem-inlaid sticks, you receive an omen: weal, woe, or neither (special).","description_es":"Lanzas varitas enjoyadas y recibes un presagio: bien, mal o ninguno (especial).","materials":"Specially marked sticks, bones, or tokens"},
  {"id":"blindness_deafness","name":{"en":"Blindness/Deafness","es":"Ceguera/Sordera"},"level":2,"school":{"en":"Necromancy","es":"Nigromancia"},"castingTime":"Action","range":"30 feet","duration":"1 minute","components":"V","classes":["Bard","Cleric","Sorcerer","Wizard"],"description_en":"You can blind or deafen a foe. One creature makes a Constitution save; on fail, blinded or deafened (your choice).","description_es":"Puedes cegar o ensordecer a un enemigo. Una criatura hace salvación de Constitución; falla: cegada o ensordecida (tú eliges).","savingThrow":"Constitution"},
  {"id":"calm_emotions","name":{"en":"Calm Emotions","es":"Calmar emociones"},"level":2,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 1 minute","components":"V, S","classes":["Bard","Cleric"],"description_en":"You attempt to suppress strong emotions in a group of creatures. Each in a 20-ft radius makes a Charisma save; charmed/frightened are unaffected by triggers; can also pacify.","description_es":"Intentas reprimir emociones fuertes en un grupo de criaturas. Radio de 6 m hace salvación de Carisma; encantadas/asustadas ya no reaccionan a estímulos; puedes también pacificar.","savingThrow":"Charisma","areaOfEffect":"20-foot radius"},
  {"id":"charm_person","name":{"en":"Charm Person","es":"Encantar persona"},"level":2,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"30 feet","duration":"1 hour","components":"V, S","classes":["Bard","Druid","Sorcerer","Warlock","Wizard"],"description_en":"You attempt to charm a humanoid you can see within range. It makes a Wisdom save; on fail, treats you as a friendly acquaintance.","description_es":"Intentas encantar a un humanoide visible. Hace salvación de Sabiduría; falla: te considera un conocido amistoso.","savingThrow":"Wisdom"},
  {"id":"continual_flame","name":{"en":"Continual Flame","es":"Llama continua"},"level":2,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"Touch","duration":"Until dispelled","components":"V, S, M","classes":["Cleric","Wizard"],"description_en":"A flame, equivalent in luminosity to a torch, springs forth from an object you touch. It creates light indefinitely — can be covered/hidden.","description_es":"De un objeto brota una llama con la luminosidad de una antorcha. Crea luz sin límite temporal; puede cubrirse/ocultarse.","materials":"Ruby dust worth 50 gp"},
  {"id":"darkness","name":{"en":"Darkness","es":"Oscuridad"},"level":2,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 10 minutes","components":"V, M","classes":["Sorcerer","Warlock","Wizard"],"description_en":"Magical darkness spreads from a point you choose. Light can't pierce it. Creatures with darkvision can't see through it.","description_es":"La oscuridad mágica se extiende desde un punto elegido. La luz no la atraviesa, ni siquiera la visión en la oscuridad.","areaOfEffect":"15-foot radius","materials":"Bat fur and a drop of pitch or coal"},
  {"id":"darkvision","name":{"en":"Darkvision","es":"Visión en la oscuridad"},"level":2,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"Touch","duration":"8 hours","components":"V, S, M","classes":["Druid","Ranger","Sorcerer","Wizard"],"description_en":"You touch a willing creature and grant it the ability to see in the dark out to 60 feet for the duration.","description_es":"Concedes a una criatura voluntaria visión en la oscuridad hasta 18 m durante 8 horas.","materials":"Either a pinch of dried carrot or an agate"},
  {"id":"detect_thoughts","name":{"en":"Detect Thoughts","es":"Detectar pensamientos"},"level":2,"school":{"en":"Divination","es":"Adivinación"},"castingTime":"Action","range":"Self","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Bard","Sorcerer","Wizard"],"description_en":"You sense the presence of thoughts within 30 feet (creatures with an Intelligence of at least 1). On your turn (action), probe deeper to read a target's thoughts.","description_es":"Percibes pensamientos a 9 m (Inteligencia ≥ 1). En tu turno (acción) puedes sondear más profundo las lecturas de un objetivo.","materials":"A copper piece"},
  {"id":"enhance_ability","name":{"en":"Enhance Ability","es":"Potenciar aptitud"},"level":2,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"Touch","duration":"Concentration, up to 1 hour","components":"V, S, M","classes":["Bard","Cleric","Druid","Sorcerer"],"description_en":"You touch a creature and choose one ability: advantage on checks with it, d10 instead of d20 in dim light/darkness, or +2 to Charisma if charmed.","description_es":"Potencias la habilidad de una criatura: ventaja en pruebas con ella, 1d10 en penumbra/oscuridad, o +2 a Carisma (encantada).","materials":"Fur or feather from the appropriate animal"},
  {"id":"enlarge_reduce","name":{"en":"Enlarge/Reduce","es":"Agrandar/Reducir"},"level":2,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"30 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"You cause a creature or object to grow larger or smaller. An unwilling creature may make a Constitution save to resist.","description_es":"Haces que una criatura u objeto crezca o se encoja. Una no voluntaria puede hacer salvación de Constitución para resistir.","savingThrow":"Constitution","materials":"A pinch of powdered iron"},
  {"id":"flaming_sphere","name":{"en":"Flaming Sphere","es":"Esfera llameante"},"level":2,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Druid","Wizard"],"description_en":"A 5-foot-diameter sphere of fire appears. Creatures ending their turn within 5 feet take 2d6 fire damage (half on Dex save). Bonus action moves it 30 ft.","description_es":"Esfera de fuego de 1,5 m. Las criaturas a 1,5 m al final de su turno reciben 2d6 fuego (mitad con Destreza). Acción adicional la mueve 9 m.","savingThrow":"Dexterity","areaOfEffect":"5-foot sphere","materials":"A bit of tallow, brimstone, and powdered iron"},
  {"id":"gust_of_wind","name":{"en":"Gust of Wind","es":"Ráfaga de viento"},"level":2,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"Self (60-foot line)","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Druid","Sorcerer","Wizard"],"description_en":"A line of strong wind 60 ft long and 10 ft wide blasts from you. Each creature starting its turn in the line must save Strength or be pushed 15 ft away.","description_es":"Línea de viento fuerte de 18 m x 3 m. Las criaturas que empiecen su turno allí deben superar Fuerza o ser empujadas 4,5 m.","savingThrow":"Strength","areaOfEffect":"60-foot line","materials":"A legume seed"},
  {"id":"hold_person","name":{"en":"Hold Person","es":"Retener persona"},"level":2,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Bard","Cleric","Druid","Sorcerer","Warlock","Wizard"],"description_en":"Choose a humanoid you can see. Target makes Wisdom save; on fail, paralyzed until end of spell (repeat save each turn).","description_es":"Elige un humanoide visible. Hace salvación de Sabiduría; falla: paralizado hasta el final (repite cada turno).","savingThrow":"Wisdom","materials":"A small piece of iron"},
  {"id":"invisibility","name":{"en":"Invisibility","es":"Invisibilidad"},"level":2,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"Touch","duration":"Concentration, up to 1 hour","components":"V, S, M","classes":["Bard","Sorcerer","Warlock","Wizard"],"description_en":"You touch a willing creature. The target becomes invisible (until they attack or cast a spell).","description_es":"Tocas a una criatura voluntaria. Se vuelve invisible hasta que ataque o lance un conjuro.","materials":"An eyelash encased in gum arabic"},
  {"id":"knock","name":{"en":"Knock","es":"Abrir"},"level":2,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"60 feet","duration":"Instantaneous","components":"V","classes":["Bard","Sorcerer","Wizard"],"description_en":"A loud knock echoes from a target object within range. Unlocks or opens a locked, stuck, or magically sealed door (magical: auto + it's also dispelled).","description_es":"Un fuerte golpe resuena en un objeto a 18 m. Desbloquea puertas cerradas, atrancadas o selladas (mágicas: éxito auto + disipadas)."},
  {"id":"levitate","name":{"en":"Levitate","es":"Levitar"},"level":2,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 10 minutes","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"A creature or object of your choice rises vertically, up to 20 feet. An unwilling creature may make a Constitution save to resist.","description_es":"Una criatura u objeto asciende verticalmente hasta 6 m. Una no voluntaria puede hacer salvación de Constitución para resistir.","savingThrow":"Constitution","materials":"A small leather loop or a piece of golden wire bent cup-shape"},
  {"id":"locate_object","name":{"en":"Locate Object","es":"Localizar objeto"},"level":2,"school":{"en":"Divination","es":"Adivinación"},"castingTime":"Action","range":"Self","duration":"Concentration, up to 10 minutes","components":"V, S, M","classes":["Bard","Cleric","Druid","Paladin","Ranger","Wizard"],"description_en":"Describe or name a specific object familiar to you. You sense its direction and distance for the duration.","description_es":"Describe o nombra un objeto específico conocido. Percibes su dirección y distancia durante la duración.","materials":"A forked twig"},
  {"id":"mirror_image","name":{"en":"Mirror Image","es":"Imagen duplicada"},"level":2,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"Self","duration":"1 minute","components":"V, S","classes":["Bard","Sorcerer","Warlock","Wizard"],"description_en":"Three duplicates appear around you. Attacker rolls a d20: 6 or lower, target a duplicate (destroyed); 7+, targets you.","description_es":"Aparecen tres duplicados a tu alrededor. El atacante tira 1d20: ≤6 apunta a un duplicado (destruido), ≥7 te apunta a ti."},
  {"id":"misty_step","name":{"en":"Misty Step","es":"Paso brumoso"},"level":2,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Bonus action","range":"Self","duration":"Instantaneous","components":"V","classes":["Sorcerer","Warlock","Wizard"],"description_en":"Briefly surrounded by silvery mist, you teleport up to 30 feet to an unoccupied space you can see.","description_es":"Un breve manto de niebla plateada te envuelve y te teletransportas hasta 9 m a un espacio libre."},
  {"id":"nystuls_magic_aura","name":{"en":"Nystul's Magic Aura","es":"Aura mágica de Nystul"},"level":2,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"Touch","duration":"24 hours","components":"V, S, M","classes":["Wizard"],"description_en":"You place an illusion on a creature or object. Choose a magic school, or make it appear magical/non-magical, or mask alignment.","description_es":"Colocas una ilusión sobre una criatura u objeto. Elige escuela mágica, hazla parecer mágica/normal, o disimula su alineación.","materials":"A small square of silk"},
  {"id":"prayer_of_healing","name":{"en":"Prayer of Healing","es":"Oración de sanación"},"level":2,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"10 minutes","range":"30 feet","duration":"Instantaneous","components":"V","classes":["Cleric","Paladin"],"description_en":"Up to six creatures of your choice regain hit points equal to 2d8 + your spellcasting modifier.","description_es":"Hasta seis criaturas recuperan 2d8 + tu modificador de lanzamiento."},
  {"id":"protection_from_poison","name":{"en":"Protection from Poison","es":"Protección contra veneno"},"level":2,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"Touch","duration":"1 hour","components":"V, S","classes":["Cleric","Druid","Paladin","Ranger"],"description_en":"You touch a creature. It gains advantage on saves vs. poison, resistance to poison damage, and immunity to the poisoned condition.","description_es":"Tocas a una criatura: ventaja en salvaciones de veneno, resistencia al daño de veneno e inmunidad al estado envenenado."},
  {"id":"scorching_ray","name":{"en":"Scorching Ray","es":"Rayo abrasador"},"level":2,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"120 feet","duration":"Instantaneous","components":"V, S","classes":["Sorcerer","Wizard"],"description_en":"You create three rays of fire. Each hits one creature (you can target the same with multiple): ranged spell attack for 2d6 fire damage each.","description_es":"Creas tres rayos de fuego. Cada uno impacta a una criatura (puedes repetir objetivo): ataque a distancia de conjuro, 2d6 fuego cada uno."},
  {"id":"see_invisibility","name":{"en":"See Invisibility","es":"Ver lo invisible"},"level":2,"school":{"en":"Divination","es":"Adivinación"},"castingTime":"Action","range":"Self","duration":"1 hour","components":"V, S, M","classes":["Bard","Sorcerer","Wizard"],"description_en":"You see invisible creatures and objects within 60 feet as if they were visible.","description_es":"Ves criaturas y objetos invisibles a 18 m como si fueran visibles.","materials":"A dash of talc and a small sprinkling of powdered silver"},
  {"id":"shatter","name":{"en":"Shatter","es":"Fragmentar"},"level":2,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"60 feet","duration":"Instantaneous","components":"V, S, M","classes":["Bard","Sorcerer","Warlock","Wizard"],"description_en":"A sudden loud ringing noise, painfully intense, erupts from a point. Creatures in 10-ft sphere make Constitution save or take 3d8 thunder damage.","description_es":"Un estrépito doloroso e intenso estalla en un punto. Criaturas en una esfera de 3 m hacen salvación de Constitución o reciben 3d8 trueno.","savingThrow":"Constitution","areaOfEffect":"10-foot sphere","materials":"A chip of mica"},
  {"id":"silence","name":{"en":"Silence","es":"Silencio"},"level":2,"school":{"en":"Illusion (Ritual)","es":"Ilusión (Ritual)"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 10 minutes","components":"V, S","classes":["Bard","Cleric","Ranger"],"description_en":"No sound can be created within or pass through a 20-ft-radius sphere. Creatures inside are deafened; verbal components cannot be cast.","description_es":"Una esfera de 6 m no emite ni transmite sonido. Las criaturas dentro quedan ensordecidas; lanzar conjuros verbales es imposible.","areaOfEffect":"20-foot-radius sphere"},
  {"id":"spider_climb","name":{"en":"Spider Climb","es":"Trepar como araña"},"level":2,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"Touch","duration":"Concentration, up to 1 hour","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"Until the spell ends, one willing creature gains the ability to move up, down, and across vertical surfaces and ceilings while leaving its hands free.","description_es":"Hasta el final, una criatura voluntaria puede moverse en superficies verticales y techos con manos libres.","materials":"A bit of spiderweb"},
  {"id":"spike_growth","name":{"en":"Spike Growth","es":"Crecimiento de espinas"},"level":2,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"150 feet","duration":"Concentration, up to 10 minutes","components":"V, S, M","classes":["Druid","Ranger"],"description_en":"Ground in a 20-foot radius twists and sprouts hard spikes. Difficult terrain; 2d4 piercing per 5 ft traveled.","description_es":"El suelo en un radio de 6 m se llena de espinas. Terreno difícil; 2d4 perforante por cada 1,5 m.","areaOfEffect":"20-foot radius","materials":"Seven sharp thorns or seven small twigs sharpened"},
  {"id":"spiritual_weapon","name":{"en":"Spiritual Weapon","es":"Arma espiritual"},"level":2,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Bonus action","range":"60 feet","duration":"1 minute","components":"V, S","classes":["Cleric"],"description_en":"You create a floating, spectral weapon within range. Make a melee spell attack: 1d8 + spellcasting modifier force damage. Move 20 ft as bonus action.","description_es":"Creas un arma espectral flotante. Ataque cuerpo a cuerpo de conjuro: 1d8 + modificador de fuerza. La mueves 6 m con acción adicional."},
  {"id":"suggestion","name":{"en":"Suggestion","es":"Sugestión"},"level":2,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"30 feet","duration":"Concentration, up to 8 hours","components":"V, M","classes":["Bard","Sorcerer","Warlock","Wizard"],"description_en":"You suggest a course of activity (one or two sentences) and magically influence a creature. Wis save; on fail, pursues that course.","description_es":"Sugieres una actividad (una o dos frases) e influyes mágicamente. Salvación de Sabiduría; falla: la persigue.","savingThrow":"Wisdom","materials":"A snake's tongue and either a bit of honeycomb or a drop of sweet oil"},
  {"id":"warding_bond","name":{"en":"Warding Bond","es":"Vínculo protector"},"level":2,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"Touch","duration":"1 hour","components":"V, S, M","classes":["Cleric"],"description_en":"You touch a creature and forge a bond. The bond gives +1 to AC + saving throws, resistance to all damage. You take same amount of damage.","description_es":"Forjas un vínculo con una criatura: +1 a CA y salvaciones, resistencia a todo daño. Tú recibes el mismo daño.","materials":"A pair of platinum rings worth at least 50 gp each that you and the target wear"},
  {"id":"web","name":{"en":"Web","es":"Telaraña"},"level":2,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 1 hour","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"Conjure a mass of thick, sticky webbing at a point. Difficult terrain; Dex save or restrained; ends on successful save each turn.","description_es":"Conjuras una masa de telarañas pegajosas. Terreno difícil; salvación de Destreza o queda apresado (repite cada turno).","savingThrow":"Dexterity","areaOfEffect":"20-foot cube","materials":"A bit of spiderweb"},
  {"id":"zone_of_truth","name":{"en":"Zone of Truth","es":"Zona de verdad"},"level":2,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"60 feet","duration":"10 minutes","components":"V, S","classes":["Bard","Cleric","Paladin"],"description_en":"You create a magical zone in a 15-foot radius that identifies lies. Creatures in zone cannot speak deliberate lies (Charisma save).","description_es":"Creas una zona mágica de 4,5 m que identifica mentiras. Las criaturas en la zona no pueden mentir deliberadamente (salvación de Carisma).","savingThrow":"Charisma","areaOfEffect":"15-foot-radius sphere"},

  # ───────────────────────────── LEVEL 3 ─────────────────────────────────
  {"id":"bestow_curse","name":{"en":"Bestow Curse","es":"Impartir maldición"},"level":3,"school":{"en":"Necromancy","es":"Nigromancy"},"castingTime":"Action","range":"Touch","duration":"Concentration, up to 1 minute","components":"V, S","classes":["Bard","Cleric","Wizard"],"description_en":"You touch a creature and choose one of three curses: disadvantage on d20 rolls, Wis save or do nothing on a turn, or target's speed -10 ft. Wis save.","description_es":"Tocas a una criatura y eliges una maldición: desventaja en 1d20, salvación de Sabiduría o no hacer nada, o -3 m de velocidad. Salvación de Sabiduría.","savingThrow":"Wisdom"},
  {"id":"blink","name":{"en":"Blink","es":"Parpadear"},"level":3,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"Self","duration":"1 minute","components":"V, S","classes":["Sorcerer","Wizard"],"description_en":"You vanish from your current plane and reappear on the Ethereal one (d20 at end of turn: 11+ on Ethereal).","description_es":"Desapareces del plano actual y apareces en el Etéreo (1d20 al final del turno: 11+ en el Etéreo)."},
  {"id":"call_lightning","name":{"en":"Call Lightning","es":"Llamar al relámpago"},"level":3,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 10 minutes","components":"V, S","classes":["Druid"],"description_en":"A storm cloud manifests. Each action to call a bolt: Dex save or 3d10 lightning damage (+1d10 in stormy conditions).","description_es":"Una nube tormentosa aparece. Acción para llamar un rayo: salvación de Destreza o 3d10 eléctrico (+1d10 si tormenta).","savingThrow":"Dexterity","areaOfEffect":"5-foot-radius"},
  {"id":"counterspell","name":{"en":"Counterspell","es":"Contrahechizo"},"level":3,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Reaction","range":"60 feet","duration":"Instantaneous","components":"S","classes":["Sorcerer","Warlock","Wizard"],"description_en":"You attempt to interrupt a creature in the process of casting a spell. If the creature's spell is 3rd or lower, it fails and no effects; 4th+ requires an ability check.","description_es":"Intentas interrumpir el lanzamiento de un conjuro. Nivel 3 o menor: falla sin efectos. 4to+: prueba de característica."},
  {"id":"daylight","name":{"en":"Daylight","es":"Luz diurna"},"level":3,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"60 feet","duration":"1 hour","components":"V, S","classes":["Cleric","Druid","Paladin","Ranger","Sorcerer"],"description_en":"A 60-foot-radius sphere of light (bright + additional dim) spreads from a point. Magical darkness of level 3 or lower is dispelled.","description_es":"Una esfera de 18 m de luz brillante (y tenue 6 m más) se extiende desde un punto. Disipa oscuridad mágica nivel 3 o menor.","areaOfEffect":"60-foot-radius sphere"},
  {"id":"dispel_magic","name":{"en":"Dispel Magic","es":"Disipar magia"},"level":3,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"120 feet","duration":"Instantaneous","components":"V, S","classes":["Bard","Cleric","Druid","Paladin","Sorcerer","Warlock","Wizard"],"description_en":"Choose any creature, object, or magical effect within range. Any spell of 3rd level or lower ends; higher requires ability check (DC 10 + spell level).","description_es":"Elige una criatura, objeto o efecto mágico a 36 m. Conjuros nivel 3 o menor terminan; mayores requieren prueba (DC 10 + nivel)."},
  {"id":"fear","name":{"en":"Fear","es":"Miedo"},"level":3,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"Self (30-foot cone)","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Bard","Sorcerer","Warlock","Wizard"],"description_en":"You project phantasmal worst fears. Each in a 30-ft cone makes Wisdom save or drops object, becomes frightened, must use action to dash away.","description_es":"Proyectas los peores miedos de las criaturas. Cono de 9 m: salvación de Sabiduría o sueltan lo que llevan, quedan asustados (acción obligatoria de correr).","savingThrow":"Wisdom","areaOfEffect":"30-foot cone","materials":"A white feather or a hen heart"},
  {"id":"fireball","name":{"en":"Fireball","es":"Bola de fuego"},"level":3,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"150 feet","duration":"Instantaneous","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"A bright streak flashes to a point and blossoms into an explosion of flame. Creatures in a 20-ft radius make Dex save or take 8d6 fire damage.","description_es":"Un destello parte hacia un punto y estalla en una explosión. Radio de 6 m: salvación de Destreza o 8d6 fuego.","savingThrow":"Dexterity","areaOfEffect":"20-foot-radius sphere","materials":"A tiny ball of bat guano and sulfur"},
  {"id":"fly","name":{"en":"Fly","es":"Volar"},"level":3,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"Touch","duration":"Concentration, up to 10 minutes","components":"V, S, M","classes":["Sorcerer","Warlock","Wizard"],"description_en":"You touch a willing creature. The target gains a flying speed of 60 feet for the duration.","description_es":"Concedes a una criatura voluntaria velocidad de vuelo 18 m.","materials":"A wing feather from any bird"},
  {"id":"gaseous_form","name":{"en":"Gaseous Form","es":"Forma gaseosa"},"level":3,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"Touch","duration":"Concentration, up to 1 hour","components":"V, S, M","classes":["Sorcerer","Warlock","Wizard"],"description_en":"You transform a willing creature into a misty cloud. Flying 10 ft, resistance to nonmagical damage, advantage on Str/Dex/Con saves.","description_es":"Transformas a una criatura voluntaria en nube brumosa. Vuela 3 m, resistencia a daño no mágico y ventaja en salvaciones F/D/C.","materials":"A bit of gauze and a wisp of smoke"},
  {"id":"haste","name":{"en":"Haste","es":"Aceleración"},"level":3,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"30 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"Choose a willing creature: +2 AC, advantage on Dex saves, doubled walking speed, and one extra action (limited: attack/spell/Dash/Disengage/Hide).","description_es":"Aceleras a una criatura: +2 CA, ventaja en salvaciones Destreza, duplica velocidad y una acción extra (ataque/conjuro/Correr/Retirarse/Esconderse).","materials":"A shaving of licorice root"},
  {"id":"hypnotic_pattern","name":{"en":"Hypnotic Pattern","es":"Patrón hipnótico"},"level":3,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 1 minute","components":"S, M","classes":["Bard","Sorcerer","Warlock","Wizard"],"description_en":"A twisting pattern of colors swirls in a 30-foot cube. Creatures failing Wisdom save are charmed, motionless, and incapacitated.","description_es":"Un patrón retorcido de colores oscila en un cubo de 9 m. Las criaturas que fallan Sabiduría quedan encantadas, quietas e incapacitadas.","savingThrow":"Wisdom","areaOfEffect":"30-foot cube","materials":"A glowing stick of incense or a crystal vial filled with phosphorescent paint"},
  {"id":"lightning_bolt","name":{"en":"Lightning Bolt","es":"Relámpago"},"level":3,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"Self (100-foot line)","duration":"Instantaneous","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"A stroke of lightning forming a line 100 ft long and 5 ft wide blasts out from you. Dex save or 8d6 lightning damage.","description_es":"Un rayo de 30 m x 1,5 m brota de ti. Salvación de Destreza o 8d6 eléctrico.","savingThrow":"Dexterity","areaOfEffect":"100-foot line","materials":"A bit of fur and a rod of amber, crystal, or glass"},
  {"id":"major_image","name":{"en":"Major Image","es":"Imagen mayor"},"level":3,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"120 feet","duration":"10 minutes","components":"V, S, M","classes":["Bard","Sorcerer","Warlock","Wizard"],"description_en":"You create a 20-foot cube image for the duration (includes sound, smell, temperature). Behaves like Silent Image but includes sensory effects.","description_es":"Creas una imagen en un cubo de 6 m con sonido, olor y temperatura. Como Imagen silenciosa pero con efectos sensoriales.","areaOfEffect":"20-foot cube","materials":"A bit of fleece"},
  {"id":"remove_curse","name":{"en":"Remove Curse","es":"Quitar maldición"},"level":3,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"Touch","duration":"Instantaneous","components":"V, S","classes":["Cleric","Paladin","Warlock","Wizard"],"description_en":"At your touch, all curses affecting one creature or object end. If the object is a cursed magic item, its curse remains but you learn its properties.","description_en":"Al tocar, todas las maldiciones de una criatura u objeto terminan. Si el objeto está maldecido mágicamente, la maldición permanece pero conoces sus propiedades.","description_es":"Al tocar, todas las maldiciones de una criatura u objeto terminan. Si es un objeto mágico maldecido, la maldición permanece pero conoces sus propiedades."},
  {"id":"revivify","name":{"en":"Revivify","es":"Revivificar"},"level":3,"school":{"en":"Necromancy","es":"Nigromancia"},"castingTime":"Action","range":"Touch","duration":"Instantaneous","components":"V, S, M","classes":["Cleric","Paladin"],"description_en":"You touch a creature that has died within the last minute. The creature returns to life with 1 hit point.","description_es":"Tocas a una criatura muerta en el último minuto. Regresa a la vida con 1 pg.","materials":"Diamonds worth 300 gp, which the spell consumes"},
  {"id":"sending","name":{"en":"Sending","es":"Recado"},"level":3,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"Unlimited","duration":"1 round","components":"V, S, M","classes":["Bard","Cleric","Wizard"],"description_en":"You send a short message (≤25 words) to a familiar creature. They hear it in their mind and can answer similarly.","description_es":"Envías un mensaje corto (≤25 palabras) a una criatura conocida. La oye en su mente y puede contestar igual.","materials":"A short piece of fine copper wire"},
  {"id":"slow","name":{"en":"Slow","es":"Lentitud"},"level":3,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"You alter time around up to six creatures in a 40-ft cube. Wis save or speed halved, -2 AC, and -2 Dex saves; can't use reactions.","description_es":"Alteras el tiempo para hasta 6 criaturas en un cubo de 12 m. Sabiduría o velocidad a la mitad, -2 CA y Destreza, sin reacciones.","savingThrow":"Wisdom","areaOfEffect":"40-foot cube","materials":"A drop of molasses"},
  {"id":"stinking_cloud","name":{"en":"Stinking Cloud","es":"Nube fétida"},"level":3,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"90 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Bard","Sorcerer","Wizard"],"description_en":"You create a 20-ft-radius sphere of yellow gas. Constitution save or poisoned (even on success the cloud obscures vision).","description_es":"Una esfera de gas amarillo de 6 m. Constitución o envenenada (incluso con éxito el gas oculta visión).","savingThrow":"Constitution","areaOfEffect":"20-foot-radius sphere","materials":"A rotten egg or skunk cabbage"},
  {"id":"tongues","name":{"en":"Tongues","es":"Idiomas"},"level":3,"school":{"en":"Divination","es":"Adivinación"},"castingTime":"Action","range":"Touch","duration":"1 hour","components":"V, M","classes":["Bard","Cleric","Sorcerer","Warlock","Wizard"],"description_en":"You touch a creature and grant it the ability to speak and understand any language for the duration.","description_es":"Concedes a una criatura hablar y entender cualquier idioma durante la hora.","materials":"A small clay model of a ziggurat"},
  {"id":"vampiric_touch","name":{"en":"Vampiric Touch","es":"Toque vampírico"},"level":3,"school":{"en":"Necromancy","es":"Nigromanía"},"castingTime":"Action","range":"Self","duration":"Concentration, up to 1 minute","components":"V, S","classes":["Sorcerer","Warlock","Wizard"],"description_en":"Your melee spell attacks through your hands deal an extra 2d6 necrotic damage, and you regain HP equal to half that.","description_es":"Tus ataques cuerpo a cuerpo de conjuro con las manos infligen +2d6 necrótico, y recuperas la mitad de pg."},
  {"id":"water_breathing","name":{"en":"Water Breathing","es":"Respirar agua"},"level":3,"school":{"en":"Transmutation (Ritual)","es":"Transmutación (Ritual)"},"castingTime":"Action","range":"30 feet","duration":"24 hours","components":"V, S, M","classes":["Druid","Ranger","Sorcerer","Wizard"],"description_en":"You grant up to ten willing creatures within range the ability to breathe underwater until the spell ends.","description_es":"Concedes a hasta 10 criaturas voluntarias a 9 m la capacidad de respirar bajo agua durante 24 horas.","materials":"A short reed or piece of straw"},

  # ───────────────────────────── LEVEL 4 ─────────────────────────────────
  {"id":"arcane_eye","name":{"en":"Arcane Eye","es":"Ojo arcano"},"level":4,"school":{"en":"Divination","es":"Adivinación"},"castingTime":"Action","range":"30 feet","duration":"Concentration, up to 1 hour","components":"V, S, M","classes":["Wizard"],"description_en":"You create an invisible magical eye. You mentally see what the eye sees (30 ft darkvision). Move it 30 ft as action.","description_es":"Creas un ojo mágico invisible. Ves a través de él (visión 9 m normal + oscuridad). Lo mueves 9 m como acción.","materials":"A bit of bat fur"},
  {"id":"banishment","name":{"en":"Banishment","es":"Destierro"},"level":4,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Cleric","Paladin","Sorcerer","Warlock","Wizard"],"description_en":"You attempt to send one creature you can see to another plane. Charisma save or banished (instant if not on its home plane).","description_es":"Intentas enviar a una criatura visible a otro plano. Salvación de Carisma o desterrada (instantáneo si no está en su plano natal).","savingThrow":"Charisma","materials":"Adversary's likeness painted in red"},
  {"id":"black_tentacles","name":{"en":"Evard's Black Tentacles","es":"Tentáculos negros de Evard"},"level":4,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"90 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Wizard"],"description_en":"Squirming black tentacles fill a 20-ft square on ground: difficult terrain. Dex save or 3d6 bludgeoning and grappled + restrained.","description_es":"Tentáculos negros llenan un cuadrado de 6 m: terreno difícil. Destreza o 3d6 contundente, agarrada y apresada.","savingThrow":"Dexterity","areaOfEffect":"20-foot square","materials":"A piece of tentacle from a giant octopus"},
  {"id":"blight","name":{"en":"Blight","es":"Plaga"},"level":4,"school":{"en":"Necromancy","es":"Nigromancia"},"castingTime":"Action","range":"30 feet","duration":"Instantaneous","components":"V, S","classes":["Druid","Sorcerer","Warlock","Wizard"],"description_en":"Necromantic energy washes a creature. Constitution save, takes 8d8 necrotic damage; plants have disadvantage.","description_es":"Energía nigromántica baña a una criatura. Constitución o 8d8 necrótico (plantas con desventaja).","savingThrow":"Constitution"},
  {"id":"compulsion","name":{"en":"Compulsion","es":"Compulsión"},"level":4,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"30 feet","duration":"Concentration, up to 1 minute","components":"V, S","classes":["Bard"],"description_en":"Creatures in a 10-ft radius must Wis save or be forced to move away from you at full speed each turn, in a direction you choose.","description_es":"Criaturas en radio de 3 m hacen salvación de Sabiduría o se ven obligadas a alejarse de ti a toda velocidad cada turno.","savingThrow":"Wisdom","areaOfEffect":"10-foot radius"},
  {"id":"confusion","name":{"en":"Confusion","es":"Confusión"},"level":4,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"90 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Bard","Druid","Sorcerer","Wizard"],"description_en":"Assaults and twists creatures' minds in a 10-ft sphere. Wis save or suffer erratic behavior (d10 each turn).","description_es":"Ataca y retuerce mentes en una esfera de 3 m. Sabiduría o comportamiento errático (tiran 1d10 cada turno).","savingThrow":"Wisdom","areaOfEffect":"10-foot-radius sphere","materials":"Three nut shells"},
  {"id":"control_water","name":{"en":"Control Water","es":"Controlar el agua"},"level":4,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"300 feet","duration":"Concentration, up to 10 minutes","components":"V, S, M","classes":["Cleric","Druid","Wizard"],"description_en":"Control any freestanding water in a cube up to 100 feet on a side: flood, part water, redirect flow, or create a whirlpool.","description_es":"Controla agua estancada en cubo de 30 m por lado: inundar, separar, redirigir, o crear remolino.","areaOfEffect":"100-foot cube","materials":"A drop of water and a pinch of dust"},
  {"id":"dimension_door","name":{"en":"Dimension Door","es":"Puerta dimensional"},"level":4,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"500 feet","duration":"Instantaneous","components":"V","classes":["Bard","Sorcerer","Warlock","Wizard"],"description_en":"You teleport from your current location to any other spot within range. You arrive exactly where you want.","description_es":"Te teletransportas de tu ubicación actual a cualquier punto dentro del alcance."},
  {"id":"fabricate","name":{"en":"Fabricate","es":"Fabricar"},"level":4,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"10 minutes","range":"120 feet","duration":"Instantaneous","components":"V, S","classes":["Wizard"],"description_en":"Convert raw materials into products of the same material. Craft a Large or smaller object (metal: Medium).","description_es":"Convierte materiales en bruto en productos del mismo material. Crea un objeto Grande o menor (metal: Mediano)."},
  {"id":"freedom_of_movement","name":{"en":"Freedom of Movement","es":"Libertad de movimiento"},"level":4,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"Touch","duration":"1 hour","components":"V, S, M","classes":["Bard","Cleric","Druid","Ranger"],"description_en":"Movement unaffected by difficult terrain; spells can't reduce speed or restrain target. Also escapes nonmagical restraints.","description_es":"Tocas a una criatura. Su movimiento no se ve afectado por terreno difícil; conjuros no pueden reducir su velocidad ni apresarla. Se libera de inmovilizaciones no mágicas.","materials":"A leather strap bound to arm"},
  {"id":"greater_invisibility","name":{"en":"Greater Invisibility","es":"Invisibilidad mayor"},"level":4,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"Touch","duration":"Concentration, up to 1 minute","components":"V, S","classes":["Bard","Sorcerer","Wizard"],"description_en":"You or a creature you touch becomes invisible. Magic that detects invisible creatures doesn't reveal the target.","description_es":"Tú o la criatura que tocas sois invisibles. La magia que detecta el silencio no os revela como objetivo."},
  {"id":"guardian_of_faith","name":{"en":"Guardian of Faith","es":"Guardián de fe"},"level":4,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"30 feet","duration":"8 hours","components":"V","classes":["Cleric"],"description_en":"A Large spectral guardian appears and hovers. Each creature within 10 ft makes Dex save or takes 20 radiant damage and is pushed 5 ft away.","description_es":"Un guardián espectral Grande aparece flotando. Criaturas dentro de 3 m hacen salvación de Destreza o 20 radiante y son empujadas 1,5 m.","savingThrow":"Dexterity","areaOfEffect":"10 feet"},
  {"id":"ice_storm","name":{"en":"Ice Storm","es":"Tormenta de hielo"},"level":4,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"300 feet","duration":"Instantaneous","components":"V, S, M","classes":["Druid","Sorcerer","Wizard"],"description_en":"Hailstones rain in 20-ft cylinder (60 ft high). 2d8 bludgeoning + 4d6 cold. Difficult terrain until end of your next turn.","description_es":"Granizo en un cilindro de 6 m (radio) x 18 m (alto). 2d8 contundente + 4d6 frío. Terreno difícil hasta tu próximo turno.","areaOfEffect":"20-foot-radius cylinder","materials":"A pinch of dust and a few drops of water"},
  {"id":"locate_creature","name":{"en":"Locate Creature","es":"Localizar criatura"},"level":4,"school":{"en":"Divination","es":"Adivinación"},"castingTime":"Action","range":"Self","duration":"Concentration, up to 1 hour","components":"V, S, M","classes":["Bard","Cleric","Druid","Paladin","Ranger","Wizard"],"description_en":"Describe or name a creature familiar to you. You sense its direction and distance. Learns if it moved beyond 1 mile.","description_es":"Describe o nombra una criatura. Percibes su dirección y distancia. Aprendes si se ha movido más allá de 1 milla.","materials":"A bit of fur from the creature"},
  {"id":"phantasmal_killer","name":{"en":"Phantasmal Killer","es":"Asesino fantasmal"},"level":4,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 1 minute","components":"V, S","classes":["Wizard"],"description_en":"You craft an illusory creature that terrifies target. Wis save or frightened 1d6 psychic at start of each turn; each turn Wis save or drop to 0 HP.","description_es":"Forjas una criatura ilusoria terrible. Sabiduría o asustado (1d6 psíquico inicial de cada turno); cada turno salva o cae a 0 pg.","savingThrow":"Wisdom"},
  {"id":"polymorph","name":{"en":"Polymorph","es":"Polimorfismo"},"level":4,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 1 hour","components":"V, S, M","classes":["Bard","Druid","Sorcerer","Wizard"],"description_en":"Transform a creature into a beast with CR equal to or less than its level (or higher with shared save). Wis save: drops to 0 HP on fail.","description_es":"Transformas a una criatura en bestia con CR ≤ su nivel (mayor si compartes). Sabiduría: cae a 0 pg si falla.","savingThrow":"Wisdom","materials":"A caterpillar cocoon"},
  {"id":"wall_of_fire","name":{"en":"Wall of Fire","es":"Muro de fuego"},"level":4,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Druid","Sorcerer","Wizard"],"description_en":"An opaque wall of fire appears in range. One side deals 5d8 fire (1d8 per 10 ft); both sides 5d8 if 20 ft thick.","description_es":"Un muro opaco de fuego aparece. Un lado: 5d8 fuego (1d8 por 3 m). Lado opuesto: 5d8 fuego.","savingThrow":"Dexterity","areaOfEffect":"One 60-ft side or 30+30 ft ringed","materials":"A small piece of phosphorus"},

  # ───────────────────────────── LEVEL 5 ─────────────────────────────────
  {"id":"animate_objects","name":{"en":"Animate Objects","es":"Animar objetos"},"level":5,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 1 minute","components":"V, S","classes":["Bard","Sorcerer","Wizard"],"description_en":"Objects come to life. Up to ten nonmagical objects become creatures under your control with attacks proportional to size.","description_es":"Hasta diez objetos no mágicos cobran vida y obedecen. Sus ataques escalan según el tamaño (danos 1d4 a 2d8)."},
  {"id":"antilife_shell","name":{"en":"Antilife Shell","es":"Caparazón antivida"},"level":5,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"Self (10-foot radius)","duration":"Concentration, up to 1 hour","components":"V, S","classes":["Druid"],"description_en":"A shimmering barrier extends from you in a 10-ft radius, preventing living creatures from passing or reaching through.","description_es":"Una barrera titilante se extiende 3 m a tu alrededor. Criaturas vivas no pueden cruzarla ni alcanzarte.","areaOfEffect":"10-foot radius"},
  {"id":"cloudkill","name":{"en":"Cloudkill","es":"Nube mortífera"},"level":5,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 10 minutes","components":"V, S","classes":["Sorcerer","Wizard"],"description_en":"You create a 20-ft-radius sphere of fog. Constitution save or 5d8 poison on starting turn there; in fog 3d8 at start of each turn thereafter.","description_es":"Esfera de niebla venenosa de 6 m. Constitución o 5d8 veneno al entrar; 3d8 cada turno allí.","savingThrow":"Constitution","areaOfEffect":"20-foot-radius sphere"},
  {"id":"commune","name":{"en":"Commune","es":"Comulgar"},"level":5,"school":{"en":"Divination (Ritual)","es":"Adivinación (Ritual)"},"castingTime":"1 minute","range":"Self","duration":"1 minute","components":"V, S, M","classes":["Cleric"],"description_en":"You contact your deity and ask up to three yes-or-no questions; you receive truthful answers.","description_es":"Contactas con tu deidad y preguntas hasta tres dudas de sí/no; recibes respuestas veraces.","materials":"Incense and a vial of holy or unholy water"},
  {"id":"cone_of_cold","name":{"en":"Cone of Cold","es":"Cono de frío"},"level":5,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"Self (60-foot cone)","duration":"Instantaneous","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"A blast of cold air erupts from your hands. Constitution save or 8d8 cold damage.","description_es":"Un estallido de aire frío brota de tus manos. Constitución o 8d8 frío.","savingThrow":"Constitution","areaOfEffect":"60-foot cone","materials":"A small crystal or glass cone"},
  {"id":"contagion","name":{"en":"Contagion","es":"Contagio"},"level":5,"school":{"en":"Necromancy","es":"Nigromancia"},"castingTime":"Action","range":"Touch","duration":"7 days","components":"V, S","classes":["Cleric","Druid"],"description_en":"You infect a creature; Constitution save or contract one disease (Blinding Sickness, Filth Fever, Flesh Rot, Mindfire, or Seizure).","description_es":"Infectas a una criatura; Constitución o contrae una enfermedad (Ceguera, Fiebre, Podredumbre, Fuego Mental, Convulsión).","savingThrow":"Constitution"},
  {"id":"dominate_person","name":{"en":"Dominate Person","es":"Dominar persona"},"level":5,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 1 minute","components":"V, S","classes":["Bard","Sorcerer","Wizard"],"description_en":"You attempt to beguile a humanoid you can see. Wis save; on fail, target obeys telepathic commands.","description_es":"Intentas hechizar a un humanoide visible. Sabiduría o obedeces tus órdenes telepáticas.","savingThrow":"Wisdom"},
  {"id":"geas","name":{"en":"Geas","es":"Geas"},"level":5,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"1 minute","range":"60 feet","duration":"30 days","components":"V","classes":["Bard","Cleric","Druid","Paladin","Wizard"],"description_en":"Place a magical command on a creature. Wis save or charmed: must carry out service or 5d10 psychic damage per day acting contrary.","description_es":"Orden mágica. Sabiduría o encantada, debe cumplir el servicio o recibir 5d10 psíquico al día por actuar en contra.","savingThrow":"Wisdom"},
  {"id":"greater_restoration","name":{"en":"Greater Restoration","es":"Restauración mayor"},"level":5,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"Touch","duration":"Instantaneous","components":"V, S, M","classes":["Bard","Cleric","Druid"],"description_en":"Imbue a creature with positive energy to undo a debilitating effect: reduce exhaustion, end charmed/petrified, remove curse, restore ability scores.","description_es":"Imbuyes energía positiva a la criatura: reduce cansancio, termina hechizos o petrificación, elimina maldiciones o restaura características.","materials":"Diamond dust worth at least 100 gp"},
  {"id":"hold_monster","name":{"en":"Hold Monster","es":"Retener monstruo"},"level":5,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"90 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Bard","Sorcerer","Warlock","Wizard"],"description_en":"Choose a creature you can see. Wis save or paralyzed until end (repeat each turn).","description_es":"Elige a una criatura visible. Sabiduría o paralizada hasta el final (repite cada turno).","savingThrow":"Wisdom","materials":"One straight piece of iron"},
  {"id":"insect_plague","name":{"en":"Insect Plague","es":"Plaga de insectos"},"level":5,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"Action","range":"300 feet","duration":"Concentration, up to 10 minutes","components":"V, S, M","classes":["Cleric","Druid"],"description_en":"A swarm of insects fills a 20-ft-radius sphere. Constitution save or 4d10 piercing; halved on success.","description_es":"Un enjambre de insectos llena una esfera de 6 m. Constitución o 4d10 perforante; mitad si éxito.","savingThrow":"Constitution","areaOfEffect":"20-foot-radius sphere","materials":"A handful of mosquitoes"},
  {"id":"legend_lore","name":{"en":"Legend Lore","es":"Conocimiento de leyendas"},"level":5,"school":{"en":"Divination","es":"Adivinación"},"castingTime":"10 minutes","range":"Self","duration":"Instantaneous","components":"V, S, M","classes":["Bard","Cleric","Wizard"],"description_en":"Name/describe a person, place, or object. The spell brings to mind a brief summary of significant lore.","description_es":"Nombra o describe una persona, lugar u objeto. Recibes un breve resumen de la leyenda o saber significativo.","materials":"Incense worth 250 gp + four ivory strips (50 gp each)"},
  {"id":"passwall","name":{"en":"Passwall","es":"Pase de pared"},"level":5,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"30 feet","duration":"1 hour","components":"V, S, M","classes":["Wizard"],"description_en":"A passage appears in a solid surface you can see (wall, tree, etc.) at least 5 ft thick and no more than 20 ft thick.","description_es":"Aparece un pasaje en una superficie sólida (≥1,5 m de grosor, ≤6 m de grosor).","materials":"A pinch of sesame seeds"},
  {"id":"raise_dead","name":{"en":"Raise Dead","es":"Alzar a los muertos"},"level":5,"school":{"en":"Necromancy","es":"Nigromancia"},"castingTime":"1 hour","range":"Touch","duration":"Instantaneous","components":"V, S, M","classes":["Bard","Cleric","Paladin"],"description_en":"Returns a dead creature (≤10 days) to life with 1 HP. Mortal wounds close; missing parts are NOT restored.","description_es":"Devuelve a la vida a una criatura muerta (≤10 días) con 1 pg. Las heridas mortales cierran; los miembros faltantes NO se restauran.","materials":"A diamond worth 500 gp, consumed"},
  {"id":"scrying","name":{"en":"Scrying","es":"Escudriñar"},"level":5,"school":{"en":"Divination","es":"Adivinación"},"castingTime":"10 minutes","range":"Self","duration":"Concentration, up to 10 minutes","components":"V, S, M","classes":["Bard","Cleric","Druid","Warlock","Wizard"],"description_en":"You can see and hear a particular creature up to 10 miles away. Wis save (varies by conditions).","description_es":"Ves y oyes a una criatura en concreto a hasta 16 km. Salvación de Sabiduría (varía).","materials":"A focus worth at least 1,000 gp, such as a crystal ball, mirror, or water-filled basin"},
  {"id":"telekinesis","name":{"en":"Telekinesis","es":"Telequinesis"},"level":5,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 10 minutes","components":"V, S","classes":["Sorcerer","Wizard"],"description_en":"You gain the ability to move or manipulate creatures or objects by thought. Move a Huge or smaller object (1,000 lb) or Grapple a creature.","description_es":"Mueves objetos (≤500 kg) y aprietas criaturas con el pensamiento hasta 10 min."},
  {"id":"wall_of_force","name":{"en":"Wall of Force","es":"Muro de fuerza"},"level":5,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 10 minutes","components":"V, S, M","classes":["Wizard"],"description_en":"An invisible wall of force springs into existence. Nothing passes through physically; lightning, cold, etc., crack through.","description_es":"Un muro invisible de fuerza aparece. Nada físico lo atraviesa; relámpagos, frío etc., tampoco.","materials":"A pinch of powder made by crushing a clear gemstone"},
  {"id":"wall_of_stone","name":{"en":"Wall of Stone","es":"Muro de piedra"},"level":5,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 10 minutes","components":"V, S, M","classes":["Druid","Sorcerer","Wizard"],"description_en":"A nonmagical wall of solid stone springs into existence. Ten 10-ft panels per 6-inch thickness (up to 6 inches).","description_es":"Aparece un muro de piedra no mágica. Diez paneles de 3 m por 15 cm de grosor.","materials":"A small block of granite"},

  # ───────────────────────────── LEVEL 6 ─────────────────────────────────
  {"id":"blade_barrier","name":{"en":"Blade Barrier","es":"Barrera de cuchillas"},"level":6,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"90 feet","duration":"Concentration, up to 10 minutes","components":"V, S","classes":["Cleric"],"description_en":"Vertical wall of whirling, razor-sharp blades of magical energy. Creatures passing through make Dex save or take 6d10 slashing.","description_es":"Muro vertical de cuchillas mágicas arremolinadas. Salvación de Destreza o 6d10 cortante (20 m × 6 m máximo).","savingThrow":"Dexterity","areaOfEffect":"Up to 100 feet long, 20 feet high"},
  {"id":"chain_lightning","name":{"en":"Chain Lightning","es":"Relámpago en cadena"},"level":6,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"150 feet","duration":"Instantaneous","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"Lightning arcs to target (Dex save or 10d6), then up to 3 additional creatures within 30 ft of each previous (half).","description_es":"El relámpago impacta al objetivo (Destreza o 10d6) y luego salta a hasta 3 criaturas adicionales a 9 m (mitad).","savingThrow":"Dexterity","materials":"A bit of fur and a rod of amber, crystal, or glass"},
  {"id":"contingency","name":{"en":"Contingency","es":"Contingencia"},"level":6,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"10 minutes","range":"Self","duration":"10 days","components":"V, S, M","classes":["Wizard"],"description_en":"Choose a spell of level 5 or lower; it activates under a trigger condition.","description_es":"Elige un conjuro preparado de nivel 5 o menor; se activa bajo una condición desencadenante específica.","materials":"A statuette of yourself carved from ivory, gems worth 1,500 gp"},
  {"id":"create_undead","name":{"en":"Create Undead","es":"Crear no-muerto"},"level":6,"school":{"en":"Necromancy","es":"Nigromancia"},"castingTime":"1 minute","range":"10 feet","duration":"Instantaneous","components":"V, S, M","classes":["Cleric","Warlock","Wizard"],"description_en":"You animate a corpse (or pile) within range as a ghoul, ghast, wight, or mummy under your control.","description_es":"Animas un cadáver (o pila) a 3 m como un ghul, ghast, espíritu o momia bajo tu control.","materials":"One black onyx stone for each corpse"},
  {"id":"disintegrate","name":{"en":"Disintegrate","es":"Desintegrar"},"level":6,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"60 feet","duration":"Instantaneous","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"A thin green ray springs from your pointing finger. Dex save or 10d6 + 50 force damage; if reduced to 0 HP, dust.","description_es":"Un delgado rayo verde brota de tu dedo. Destreza o 10d6 + 50 de fuerza; si baja a 0 pg, queda hecho polvo.","savingThrow":"Dexterity","materials":"A magnet and a powdered jewel"},
  {"id":"freezing_sphere","name":{"en":"Otiluke's Freezing Sphere","es":"Esfera congelante de Otiluke"},"level":6,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"300 feet","duration":"Instantaneous","components":"V, S, M","classes":["Wizard"],"description_en":"A frigid globe of cold energy launches toward a point. In 60-ft range: 10d6 cold (Dex save half). At impact: 3-ft radius freezing.","description_es":"Un globo frío de energía fría. Línea de 18 m o a 90 m: 10d6 frío (Destreza mitad). Impacto: congelación 90 cm.","savingThrow":"Dexterity","materials":"A small crystal sphere"},
  {"id":"globe_of_invulnerability","name":{"en":"Globe of Invulnerability","es":"Globo de invulnerabilidad"},"level":6,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"Action","range":"Self (10-foot radius)","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"An immobile, shimmering sphere surrounds you, preventing non-ranged spells of level 5 or lower from affecting those inside.","description_es":"Una esfera titilante inmóvil te rodea. Conjuros nivel 5 o menor lanzados desde fuera no afectan a los de dentro.","areaOfEffect":"10-foot radius","materials":"A glass or crystal bead that shatters when the spell ends"},
  {"id":"guards_and_wards","name":{"en":"Guards and Wards","es":"Guardianes y custodios"},"level":6,"school":{"en":"Abjuration","es":"Abjuración"},"castingTime":"10 minutes","range":"Touch","duration":"24 hours","components":"V, S, M","classes":["Wizard"],"description_en":"You create a number of magical effects in a permanent ward around a location: fog, permanent magic mouths, stinking clouds, gusts, suggested zones, lost areas.","description_es":"Creas efectos mágicos alrededor de una ubicación permanente: niebla, bocas mágicas perpetuas, nubes fétidas, ráfagas, áreas de sugerencias, zonas perdidas.","materials":"A burning brand, a stick of incense, a strip of white cloth"},
  {"id":"magic_jar","name":{"en":"Magic Jar","es":"Tarro mágico"},"level":6,"school":{"en":"Necromancy","es":"Nigromancia"},"castingTime":"1 minute","range":"Self","duration":"Until dispelled","components":"V, S, M","classes":["Wizard"],"description_en":"Your soul is placed in a jar; your body falls catatonic. You can possess any creature within 100 ft, possessing/harm them.","description_es":"Tu alma pasa a un tarro; tu cuerpo entra en estado catatónico. Puedes poseer (o dañar) a una criatura a 30 m.","materials":"A gem, crystal, or reliquary worth at least 500 gp"},
  {"id":"mass_suggestion","name":{"en":"Mass Suggestion","es":"Sugestión en masa"},"level":6,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"60 feet","duration":"Concentration, up to 24 hours","components":"V, M","classes":["Bard","Sorcerer","Warlock","Wizard"],"description_en":"Up to twelve Wis save targets within range pursue a course of activity.","description_es":"Hasta doce objetivos en 18 m hacen salvación de Sabiduría o persiguen la actividad sugerida.","savingThrow":"Wisdom","materials":"A snake's tongue and honeycomb or sweet oil"},
  {"id":"otto_s_irresistible_dance","name":{"en":"Otto's Irresistible Dance","es":"Danza irresistible de Otto"},"level":6,"school":{"en":"Enchantment","es":"Encantamiento"},"castingTime":"Action","range":"30 feet","duration":"Concentration, up to 1 minute","components":"V","classes":["Bard","Wizard"],"description_en":"Choose one creature within range. Wis save; on fail, must dance until end. No actions; disadvantage on Dex; provokes opportunity attacks.","description_es":"Elige una criatura a 9 m. Sabiduría o debe bailar hasta el final: sin acciones, desventaja en Destreza, expone ataques de oportunidad.","savingThrow":"Wisdom"},
  {"id":"planar_ally","name":{"en":"Planar Ally","es":"Aliado planar"},"level":6,"school":{"en":"Conjuration","es":"Conjuración"},"castingTime":"10 minutes","range":"60 feet","duration":"Instantaneous","components":"V, S","classes":["Cleric"],"description_en":"You request an entity from another plane. It performs one service (limited to 2 hrs of work) in exchange for payment.","description_es":"Solicitas una entidad de otro plano. Realiza un servicio (≤2 h de trabajo) a cambio de un pago designado."},
  {"id":"programmed_illusion","name":{"en":"Programmed Illusion","es":"Ilusión programada"},"level":6,"school":{"en":"Illusion","es":"Ilusión"},"castingTime":"Action","range":"120 feet","duration":"Until dispelled","components":"V, S, M","classes":["Bard","Wizard"],"description_en":"An illusion becomes a trap. Each time a creature enters a 30-ft cube or stays within it, the illusion activates (sound/sight).","description_es":"Una ilusión se convierte en trampa. Cada vez que una criatura entre o permanezca en un cubo de 9 m, la ilusión se dispara.","areaOfEffect":"30-foot cube","materials":"A bit of fleece and jade dust worth at least 25 gp"},
  {"id":"soul_cage","name":{"en":"Soul Cage","es":"Jaula de almas"},"level":6,"school":{"en":"Necromancy","es":"Nigromancy"},"castingTime":"Action","range":"60 feet","duration":"8 hours","components":"V, S, M","classes":["Wizard"],"description_en":"You use a Small or Medium corpse to lure the soul of a creature that died in the last 24 hours. Trap the soul — you interrogate, spy, trap, or take 2d8/1d6/2d10 resources.","description_es":"Usas un cadáver Pequeño o Mediano para atrapar el alma de una criatura muerta en las últimas 24 h. Luego interrogar, espiar, atrapar o tomar recursos.","materials":"A tiny silver cage worth 100 gp"},
  {"id":"true_seeing","name":{"en":"True Seeing","es":"Visión verdadera"},"level":6,"school":{"en":"Divination","es":"Adivinación"},"castingTime":"Action","range":"Touch","duration":"1 hour","components":"V, S, M","classes":["Bard","Cleric","Sorcerer","Warlock","Wizard"],"description_en":"You touch a willing creature: it sees all things as they truly are (invisible, illusions, magic auras). 120 ft Truesight.","description_es":"Concedes a una criatura voluntaria ver todo como realmente es: invisibles, ilusiones, auras mágicas. Visión verdadera 36 m.","materials":"A magnifying glass with a handle made of bone or ivory"},
  {"id":"wall_of_ice","name":{"en":"Wall of Ice","es":"Muro de hielo"},"level":6,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"120 feet","duration":"Concentration, up to 10 minutes","components":"V, S, M","classes":["Wizard"],"description_en":"A solid wall of ice. Hp 30 (10 ft) or 60 (10 in. thick). Cold damage to those within 10 ft, 5d8 halves. Can shatter 3d8 + Str.","description_es":"Muro sólido de hielo. pg 30 (3 m) o 60 (25 cm). Daño frío 5d8 en 3 m, mitad. Destruye: 3d8 + Fuerza.","savingThrow":"Dexterity","materials":"A small piece of quartz"},

  # ───────────────────────────── LEVEL 7 ─────────────────────────────────
  {"id":"crown_of_stars","name":{"en":"Crown of Stars","es":"Corona de estrellas"},"level":7,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"Self","duration":"Concentration, up to 1 minute","components":"V, S","classes":["Sorcerer","Wizard"],"description_en":"Seven motes of starry light orbit around you. Bonus action to launch (2d12 radiant) and consume one. Use 7 motes total.","description_es":"Siete motas de luz estelar orbitan a tu alrededor. Lanzar una con acción adicional: 2d12 radiante. Tienes 7 motas."},
  {"id":"delayed_blast_fireball","name":{"en":"Delayed Blast Fireball","es":"Bola de fuego retrasada"},"level":7,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"150 feet","duration":"Concentration, up to 1 minute","components":"V, S, M","classes":["Sorcerer","Wizard"],"description_en":"A glowing bead (rock in hand). Behaves like Fireball (8d6) until concentration ends, gaining +1d6 per round (max 12d6).","description_es":"Una perla brillante. Comportamiento de Bola de fuego (8d6) ganando +1d6 por ronda, hasta 12d6.","savingThrow":"Dexterity","areaOfEffect":"20-foot-radius sphere","materials":"A ball of bat guano and sulfur"},
  {"id":"divine_word","name":{"en":"Divine Word","es":"Palabra divina"},"level":7,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"30 feet","duration":"Instantaneous","components":"V","classes":["Cleric"],"description_en":"Speak a word infused with the power of creation. Up to 50 HP: stunned; 41-100: paralyzed; 21-40: blinded/deafened/frightened; 20-: killed.","description_es":"Pronuncias una palabra de creación. ≤50 pg: aturdido; 41-100: paralizado; 21-40: ciego/sordo/asustado; ≤20: muere.","savingThrow":"Charisma"},
  {"id":"etherealness","name":{"en":"Etherealness","es":"Etérea"},"level":7,"school":{"en":"Transmutation","es":"Transmutación"},"castingTime":"Action","range":"Self","duration":"Up to 8 hours","components":"V, S","classes":["Bard","Cleric","Sorcerer","Wizard"],"description_en":"You step into the border regions of the Ethereal Plane. You can see and be seen from there; move freely in 3D space.","description_es":"Pasas al borde del Plano Etéreo. Ves y eres visto desde allí; puedes moverte en 3D."},
  {"id":"finger_of_death","name":{"en":"Finger of Death","es":"Dedo de la muerte"},"level":7,"school":{"en":"Necromancy","es":"Nigromancia"},"castingTime":"Action","range":"60 feet","duration":"Instantaneous","components":"V, S","classes":["Sorcerer","Wizard"],"description_en":"A spectral finger emerges, pointing at a creature within range. Constitution save or 7d8 + 30 necrotic damage; rises as zombie on kill.","description_es":"Un dedo espectral señala a una criatura a 18 m. Constitución o 7d8 + 30 necrótico; si muere, se alza como zombi.","savingThrow":"Constitution"},
  {"id":"fire_storm","name":{"en":"Fire Storm","es":"Tormenta de fuego"},"level":7,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"150 feet","duration":"Instantaneous","components":"V, S","classes":["Cleric","Druid","Sorcerer"],"description_en":"A storm of fire rains in a 10-ft-radius cylinder 60 ft high. Each creature makes Dex save or takes 7d10 fire (half on success).","description_es":"Una tormenta de fuego llueve (cilindro de 3 m radio × 18 m). Destreza o 7d10 fuego.","savingThrow":"Dexterity","areaOfEffect":"10-ft-radius cylinder"},
  {"id":"forcecage","name":{"en":"Forcecage","es":"Jaula de fuerza"},"level":7,"school":{"en":"Evocation","es":"Evocación"},"castingTime":"Action","range":"100 feet","duration":"1 hour","components":"V, S, M","classes":["Bard","Warlock","Wizard"],"description_en":"An invisible cube of magical force (10- or 20-ft) appears around an area. The prison is a cage (telepathy barred) or solid box.","description_es":"Un cubo invisible de fuerza mágica (3 o 6 m) aparece alrededor de un área. Puede ser una jaula o una caja sólida.","areaOfEffect":"10-foot or 20-foot cube","materials":"Ruby dust worth 1,500 gp"},
