# ------------------------------------------------------------ flatten walker

# Reuses the same dict-of-properties pattern from v3/v4 monster scripts.
SPANISH_SCHOOLS = {
    "Abjuration": "Abjuración", "Conjuration": "Conjuración", "Divination": "Adivinación",
    "Enchantment": "Encantamiento", "Evocation": "Evocación", "Illusion": "Ilusión",
    "Necromancy": "Nigromancia", "Transmutation": "Transmutación",
}

def localize(val, lang):
    """Walker that flattens bilingual dicts ({"en":..., "es":...}) into a single lang."""
    if isinstance(val, dict) and "en" in val and "es" in val and set(val.keys()) <= {"en", "es"}:
        return val.get(lang, val.get("en" if lang == "es" else "es", ""))
    if isinstance(val, list):
        return [localize(v, lang) for v in val]
    if isinstance(val, dict):
        return {k: localize(v, lang) for k, v in val.items()}
    return val

def localize_school(school_dict, lang):
    """For the school field, apply canonical Spanish school name from EN mapping."""
    if lang == "en":
        return school_dict["en"]
    en_school = school_dict["en"]
    # Map "Divination (Ritual)" → "Adivinación (Ritual)"
    base = en_school
    suffix = ""
    if base.endswith(" (Ritual)"):
        base = base[:-len(" (Ritual)")]
        suffix = " (Ritual)"
    return SPANISH_SCHOOLS.get(base, school_dict["es"]) + suffix

# ------------------------------------------------------------ merge & write

def read_or_empty(path):
    if not path.exists():
        return []
    try:
        return json.load(open(path, encoding="utf-8"))
    except Exception:
        return []

def main():
    existing_en = read_or_empty(EN_FILE)
    existing_es = read_or_empty(ES_FILE)
    existing_ids_en = {s.get("id") for s in existing_en if isinstance(s, dict)}
    existing_ids_es = {s.get("id") for s in existing_es if isinstance(s, dict)}

    added_en, added_es = [], []
    skipped = []
    for s in SPELLS:
        sid = s["id"]
        if sid in existing_ids_en or sid in existing_ids_es:
            skipped.append(sid)
            continue
        en_rec = localize(s, "en")
        es_rec = localize({**s, "school": localize_school(s["school"], "es")}, "es")
        # School returned flat in en/es after localize; ensure list-of-fields order doesn't matter (we save flat)
        added_en.append(en_rec)
        added_es.append(es_rec)

    combined_en = existing_en + added_en
    combined_es = existing_es + added_es
    sort_key = lambda r: (r.get("level", 0), r.get("name", ""))
    combined_en.sort(key=sort_key)
    combined_es.sort(key=sort_key)

    EN_FILE.parent.mkdir(parents=True, exist_ok=True)
    with open(EN_FILE, "w", encoding="utf-8") as f:
        json.dump(combined_en, f, ensure_ascii=False, indent=2)
    with open(ES_FILE, "w", encoding="utf-8") as f:
        json.dump(combined_es, f, ensure_ascii=False, indent=2)

    print(f"Wrote {len(combined_en)} total EN entries ({len(added_en)} added; skipped {len(skipped)} already-present)")
    print(f"Wrote {len(combined_es)} total ES entries ({len(added_es)} added)")
    if skipped:
        print(f"  Skipped existing IDs: {skipped}")

if __name__ == "__main__":
    main()
